    #[test]
    fn compute_address_wraps_signed_offsets() {
        let interp = SmirInterpreter::new();
        let rax = VReg::Arch(ArchReg::X86(X86Reg::Rax));
        let rbx = VReg::Arch(ArchReg::X86(X86Reg::Rbx));
        let fs_base = VReg::Arch(ArchReg::X86(X86Reg::FsBase));

        let mut ctx = SmirContext::new_x86_64();
        ctx.pc = i64::MIN as u64;
        ctx.write_vreg(rax, i64::MIN as u64);
        ctx.write_vreg(rbx, i64::MIN as u64);
        ctx.write_vreg(fs_base, i64::MIN as u64);

        assert_eq!(
            interp.compute_address(
                &ctx,
                &Address::BaseOffset {
                    base: rax,
                    offset: -1,
                    disp_size: DispSize::Auto,
                },
            ),
            (i64::MIN as u64).wrapping_add((-1i64) as u64)
        );
        assert_eq!(
            interp.compute_address(
                &ctx,
                &Address::BaseIndexScale {
                    base: Some(rax),
                    index: rbx,
                    scale: 8,
                    disp: -1,
                    disp_size: DispSize::Auto,
                },
            ),
            (i64::MIN as u64)
                .wrapping_add((i64::MIN as u64).wrapping_mul(8))
                .wrapping_add((-1i64) as u64)
        );
        assert_eq!(
            interp.compute_address(
                &ctx,
                &Address::PcRel {
                    offset: -1,
                    disp_size: DispSize::Auto,
                    base: None,
                },
            ),
            (i64::MIN as u64).wrapping_add((-1i64) as u64)
        );
        assert_eq!(
            interp.compute_address(
                &ctx,
                &Address::SegmentRel {
                    segment: fs_base,
                    base: Some(rax),
                    index: Some(rbx),
                    scale: 8,
                    disp: -1,
                },
            ),
            (i64::MIN as u64)
                .wrapping_add(i64::MIN as u64)
                .wrapping_add((i64::MIN as u64).wrapping_mul(8))
                .wrapping_add((-1i64) as u64)
        );
    }

    #[test]
    fn vector_lane_insert_extract_preserve_other_bits_and_extend_exactly() {
        let interp = SmirInterpreter::new();
        let mut ctx = SmirContext::new_x86_64();
        let mut memory = FlatMemory::new(0x1000);
        let xmm0 = VReg::Arch(ArchReg::X86(X86Reg::Xmm(0)));
        let xmm1 = VReg::Arch(ArchReg::X86(X86Reg::Xmm(1)));
        let rax = VReg::Arch(ArchReg::X86(X86Reg::Rax));
        let rcx = VReg::Arch(ArchReg::X86(X86Reg::Rcx));
        let rdx = VReg::Arch(ArchReg::X86(X86Reg::Rdx));
        let mut original = [0u64; 16];
        original[0] = 0x8001_3344_5566_7788;
        original[1] = 0x99AA_BBCC_DDEE_FF00;
        SmirInterpreter::write_vec(&mut ctx, xmm0, original);
        ctx.write_vreg(rax, 0xDEAD_BEEF);

        interp
            .execute_op(
                &mut ctx,
                &mut memory,
                &SmirOp::new(
                    OpId(0),
                    0x1000,
                    OpKind::VInsertLane {
                        dst: xmm1,
                        vec: xmm0,
                        scalar: rax,
                        lane: 1,
                        elem: VecElementType::I32,
                    },
                ),
            )
            .unwrap();
        let inserted = SmirInterpreter::read_vec(&ctx, xmm1);
        assert_eq!(inserted[0], 0xDEAD_BEEF_5566_7788);
        assert_eq!(inserted[1..], original[1..]);
        assert_eq!(SmirInterpreter::read_vec(&ctx, xmm0), original);

        for (dst, sign, expected) in [
            (rcx, SignExtend::Zero, 0x8001),
            (rdx, SignExtend::Sign, 0xFFFF_FFFF_FFFF_8001),
        ] {
            interp
                .execute_op(
                    &mut ctx,
                    &mut memory,
                    &SmirOp::new(
                        OpId(1),
                        0x1000,
                        OpKind::VExtractLane {
                            dst,
                            vec: xmm0,
                            lane: 3,
                            elem: VecElementType::I16,
                            sign,
                        },
                    ),
                )
                .unwrap();
            assert_eq!(ctx.read_vreg(dst), expected);
        }
    }

    #[test]
    fn fp_to_int_honors_rounding_mode() {
        let interp = SmirInterpreter::new();
        let src = VReg::Arch(ArchReg::Arm(ArmReg::V(1)));
        let dst = VReg::Arch(ArchReg::Arm(ArmReg::X(0)));
        let mut memory = FlatMemory::new(0x1000);

        let cases: [(FpRoundMode, f64, u64); 7] = [
            (FpRoundMode::RoundNearest, 2.5, 2_u64),
            (FpRoundMode::RoundNearestTiesAway, 2.5, 3),
            (FpRoundMode::RoundNearestTiesAway, -2.5, (-3_i64) as u64),
            (FpRoundMode::RoundUp, 2.1, 3),
            (FpRoundMode::RoundDown, -2.1, (-3_i64) as u64),
            (FpRoundMode::RoundTowardZero, -2.9, (-2_i64) as u64),
            (FpRoundMode::Dynamic, 2.1, 3),
        ];

        for (mode, input, expected) in cases {
            let mut ctx = SmirContext::new_aarch64();
            ctx.write_vreg(src, input.to_bits());
            if mode == FpRoundMode::Dynamic {
                ctx.write_vreg(VReg::Arch(ArchReg::Arm(ArmReg::Fpcr)), 0b01 << 22);
            }

            interp
                .execute_op(
                    &mut ctx,
                    &mut memory,
                    &SmirOp::new(
                        OpId(0),
                        0x1000,
                        OpKind::FpToInt {
                            dst,
                            src,
                            fp_precision: FpPrecision::F64,
                            int_width: OpWidth::W64,
                            signed: true,
                            round: mode,
                        },
                    ),
                )
                .unwrap();

            assert_eq!(ctx.read_vreg(dst), expected, "{mode:?} input {input}");
        }
    }

